  List<Map<String,Object>> applications(String status,String term)throws Exception{String sql="SELECT a.id,a.status,a.created_at AS createdAt,a.applicant_name AS applicantName,a.applicant_username AS applicantUsername,b.name AS branchName,o.name AS outletName,c.asset_type AS assetType,c.name AS category,s.name AS subcategory,a.asset_code AS assetCode,a.device_type AS deviceType,a.user_name AS userName,a.user_unified_auth_id AS userUnifiedAuthId,a.recommended_range_type AS recommendedRangeType,a.final_range_type AS finalRangeType,a.approval_opinion AS approvalOpinion,a.rejection_reason AS rejectionReason,a.reviewed_at AS reviewedAt,reviewer.username AS reviewer,p.ip_address AS finalIpAddress,r.cidr AS finalCidr,d.status AS assignmentStatus,d.assigned_at AS assignedAt,d.released_at AS releasedAt FROM ip_application a LEFT JOIN asset_subcategory s ON s.id=a.subcategory_id LEFT JOIN asset_category c ON c.id=a.category_id JOIN branch b ON b.id=a.branch_id JOIN outlet o ON o.id=a.outlet_id LEFT JOIN sys_user reviewer ON reviewer.id=a.reviewed_by LEFT JOIN ip_assignment d ON d.application_id=a.id LEFT JOIN ip_address_pool p ON p.id=d.ip_pool_id LEFT JOIN ip_range r ON r.id=p.ip_range_id WHERE 1=1";List<Object>x=new ArrayList<Object>();if(optionalValue(status)!=null){sql+=" AND a.status=?";x.add(status);}if(optionalValue(term)!=null){sql+=" AND (a.user_name LIKE ? OR a.user_unified_auth_id LIKE ? OR a.asset_code LIKE ? OR s.name LIKE ? OR a.applicant_username LIKE ?)";for(int i=0;i<5;i++)x.add("%"+term.trim()+"%");}return list(sql+" ORDER BY a.id DESC",x.toArray());}
