  private static Map<String,Object> one(Connection c,String sql,Object...args)throws Exception{List<Map<String,Object>>x=list(c,sql,args);return x.isEmpty()?null:x.get(0);}
  private Map<String,Object> one(String sql,Object...args)throws Exception{try(Connection c=open()){return one(c,sql,args);}}
