  private static boolean exists(Connection c,String sql,Object...args)throws Exception{return one(c,sql,args)!=null;}
  private static void bind(PreparedStatement p,Object...args)throws Exception{for(int i=0;i<args.length;i++){Object x=args[i];if(x==null)p.setNull(i+1,Types.VARCHAR);else if(x instanceof Long)p.setLong(i+1,((Long)x).longValue());else if(x instanceof Integer)p.setInt(i+1,((Integer)x).intValue());else p.setString(i+1,String.valueOf(x));}}
