  private static Map<String,Object> map(Object...v){Map<String,Object>x=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)x.put(String.valueOf(v[i]),v[i+1]);return x;} private static long n(Object x){return x==null?0:((Number)x).longValue();} private static String value(Object x){return x==null?"":String.valueOf(x);} private static String blank(String x){return x==null||x.trim().isEmpty()?null:x.trim();} private static String optionalValue(String x){return blank(x);} private static String optional(JsonObject x,String key,int max){if(!x.has(key)||x.get(key).isJsonNull())return null;String v=x.get(key).getAsString().trim();if(v.length()>max)throw problem("FIELD_INVALID",key+" 格式不正确。");return v.isEmpty()?null:v;} private static String required(JsonObject x,String key,int max){String v=optional(x,key,max);if(v==null)throw problem("FIELD_REQUIRED",key+" 为必填项。");return v;} private static long number(JsonObject x,String key){try{return x.get(key).getAsLong();}catch(Exception e){throw problem("FIELD_INVALID",key+" 必须是编号。");}} private static int integer(JsonObject x,String key,int fallback){try{return !x.has(key)||x.get(key).isJsonNull()?fallback:x.get(key).getAsInt();}catch(Exception e){throw problem("FIELD_INVALID",key+" 必须是整数。");}} private static void assertType(String t){for(String x:TYPES)if(x.equals(t))return;throw problem("RANGE_TYPE_INVALID","网段类型不正确。");}
  private static void ip(String s){String[]x=s.split("\\.");if(x.length!=4)throw problem("IP_INVALID","IP 地址格式不正确。");for(String v:x)try{int n=Integer.parseInt(v);if(n<0||n>255)throw new Exception();}catch(Exception e){throw problem("IP_INVALID","IP 地址格式不正确。");}}
  private static boolean fullIp(String s){try{ip(s);return true;}catch(Exception e){return false;}}
  private static String mask(int prefix){long x=prefix==0?0:(0xffffffffL<<(32-prefix))&0xffffffffL;return Net.text(x);} private static String json(String x){return x.replace("\\","\\\\").replace("\"","\\\"");}
  private static String read(InputStream in)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[]b=new byte[256];int n;while((n=in.read(b))>=0)o.write(b,0,n);return new String(o.toByteArray(),StandardCharsets.UTF_8);} private static Long parseElapsed(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?:time|时间)[=<]\\s*(\\d+)",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(s);return m.find()?Long.valueOf(m.group(1)):null;}
  static PhaseTwoService.Problem problem(String code,String message){return new PhaseTwoService.Problem(400,code,message);} static final class Rule{final long id;final int blockPrefix,segmentPrefix,gatewayOffset;final String dnsPrimary,dnsSecondary;Rule(long i,int b,int s,int g,String d,String d2){id=i;blockPrefix=b;segmentPrefix=s;gatewayOffset=g;dnsPrimary=d;dnsSecondary=d2;}} static final class Segment{final String code,name;final int offset;final boolean enabled;Segment(String c,String n,int o,boolean e){code=c;name=n;offset=o;enabled=e;}} static final class Net{final long start,end;final int prefix;final String canonical;Net(long s,int p){start=s;prefix=p;end=s+((1L<<(32-p))-1);canonical=text(s)+"/"+p;}static Net parse(String x){try{String[]a=x.split("/");if(a.length!=2)throw new Exception();int p=Integer.parseInt(a[1]);if(p<0||p>30)throw new Exception();long ip=ipv4(a[0]),mask=p==0?0:(0xffffffffL<<(32-p))&0xffffffffL;if((ip&mask)!=ip)throw new Exception();return new Net(ip,p);}catch(Exception e){throw problem("CIDR_INVALID","CIDR 格式不正确。");}}static long ipv4(String x){String[]a=x.split("\\.");if(a.length!=4)throw new IllegalArgumentException();long r=0;for(String v:a){int n=Integer.parseInt(v);if(n<0||n>255)throw new IllegalArgumentException();r=(r<<8)|n;}return r;}static String text(long x){return ((x>>>24)&255)+"."+((x>>>16)&255)+"."+((x>>>8)&255)+"."+(x&255);}boolean contains(long x){return x>=start&&x<=end;}}
